import {config,configured} from './cms-api.js';
export function startAnalytics(enabled=true){
 if(!configured||!enabled||window.parent!==window||location.search.includes('preview=')||['localhost','127.0.0.1','terminal.local'].includes(location.hostname))return;
 let owner=false,optout=false;try{owner=!!sessionStorage.getItem('portfolio-owner-session');optout=localStorage.getItem('portfolio-analytics-optout')==='1';}catch{}if(owner)return;
 const privacy=document.createElement('details');privacy.className='analytics-privacy';const summary=document.createElement('summary');summary.textContent='Privacy & audience measurement';const copy=document.createElement('p');copy.textContent='This portfolio counts page views and link clicks to understand which work interests visitors. No names, emails, raw IP addresses or chat messages are stored in analytics. An identifier in this tab groups visits and resets on the server each day. Records are retained for up to 90 days and removed on the next recorded event. Do Not Track and Global Privacy Control are respected.';const toggle=document.createElement('button');toggle.type='button';const label=()=>{toggle.textContent=optout?'Allow audience measurement':'Turn off audience measurement';};label();toggle.onclick=()=>{optout=!optout;try{localStorage.setItem('portfolio-analytics-optout',optout?'1':'0');}catch{}label();};privacy.append(summary,copy,toggle);document.querySelector('footer')?.append(privacy);
 const blocked=()=>optout||navigator.doNotTrack==='1'||navigator.globalPrivacyControl===true;
 let session;function getSession(){if(session)return session;try{session=sessionStorage.getItem('portfolio-visit');if(!session){session=crypto.randomUUID();sessionStorage.setItem('portfolio-visit',session);}}catch{session=crypto.randomUUID();}return session;}
 const page=location.pathname.startsWith('/skills')?'/skills/':'/';let referrer='';try{const r=new URL(document.referrer);if(r.hostname!==location.hostname)referrer=r.hostname.slice(0,120);}catch{}
 let count=0,lastClick=0;
 const send=(event,target='')=>{if(blocked()||count>=30)return;count++;fetch(config.url+'/functions/v1/portfolio-analytics',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),session:getSession(),event,page,target,referrer,device:innerWidth<768?'mobile':innerWidth<1024?'tablet':'desktop'}),keepalive:true,signal:AbortSignal.timeout(7000)}).catch(()=>{});};
 if(document.visibilityState==='visible')send('pageview');else document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')send('pageview');},{once:true});
 document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||Date.now()-lastClick<750)return;let event='',target='';if(a.closest('#aven')){event='project_click';target='aven';}else if(a.closest('#smartstudy')){event='project_click';target='smartstudy';}else if(a.id==='fgb'||a.id==='sarra'){event='project_click';target=a.id;}else if(a.closest('#collection-projects')){event='project_click';target='additional-project';}else if(a.textContent.includes('View résumé')){event='resume_click';target='resume';}else if(a.getAttribute('href')?.startsWith('mailto:')){event='contact_click';target='email';}else if(a.closest('.social-row')||a.closest('.artist-note')){event='contact_click';try{target=new URL(a.href).hostname;}catch{return;}}if(event){lastClick=Date.now();send(event,target);}});
}
